import wave
from piper import PiperVoice

# Load your model (automatically looks for model.onnx.json in the same folder)
voice = PiperVoice.load("/srv/media/baymax/baymax.onnx")

text = "Hello world, this is my custom voice."
output_filename = "output.wav"

with wave.open(output_filename, "wb") as wav_file:
    # Write audio frames generated by Piper
    voice.synthesize(text, wav_file)

print(f"Audio saved to {output_filename}")
